import{_ as e,o as a,c as s,O as n}from"./chunks/framework.2c2d5a61.js";const b=JSON.parse('{"title":"大模型基础","description":"","frontmatter":{},"headers":[],"relativePath":"backend/AI-Agent/01-大模型基础.md","filePath":"backend/AI-Agent/01-大模型基础.md","lastUpdated":1793005160000}'),r={name:"backend/AI-Agent/01-大模型基础.md"};function o(d,t,l,p,i,c){return a(),s("div",null,t[0]||(t[0]=[n(`<h1 id="大模型基础" tabindex="-1">大模型基础 <a class="header-anchor" href="#大模型基础" aria-label="Permalink to &quot;大模型基础&quot;">​</a></h1><blockquote><p>这一篇的目标很具体：<strong>能算清一次调用多少钱、能选对模型、能解释为什么它有时候胡说</strong>。Transformer 的公式不用背，但「为什么长上下文贵」必须能讲明白。</p></blockquote><h2 id="_1-llm-到底在做什么" tabindex="-1">1. LLM 到底在做什么 <a class="header-anchor" href="#_1-llm-到底在做什么" aria-label="Permalink to &quot;1. LLM 到底在做什么&quot;">​</a></h2><p>大模型本质是一个<strong>概率函数</strong>：给定前面的 token 序列，输出下一个 token 的概率分布。生成就是不断「采样一个词 → 接到序列后面 → 再预测」的循环。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">输入: &quot;今天天气真&quot;</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 模型</span></span>
<span class="line"><span style="color:#e1e4e8;">概率: { &quot;好&quot;: 0.62, &quot;不错&quot;: 0.15, &quot;热&quot;: 0.08, ... }</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 采样</span></span>
<span class="line"><span style="color:#e1e4e8;">输出: &quot;好&quot;</span></span>
<span class="line"><span style="color:#e1e4e8;">  ↓ 拼回输入</span></span>
<span class="line"><span style="color:#e1e4e8;">&quot;今天天气真好&quot; → 继续预测下一个</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">输入: &quot;今天天气真&quot;</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 模型</span></span>
<span class="line"><span style="color:#24292e;">概率: { &quot;好&quot;: 0.62, &quot;不错&quot;: 0.15, &quot;热&quot;: 0.08, ... }</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 采样</span></span>
<span class="line"><span style="color:#24292e;">输出: &quot;好&quot;</span></span>
<span class="line"><span style="color:#24292e;">  ↓ 拼回输入</span></span>
<span class="line"><span style="color:#24292e;">&quot;今天天气真好&quot; → 继续预测下一个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这解释了三件事：</p><ol><li><strong>为什么有随机性</strong>：它是采样，不是查表；<code>temperature</code> 调的就是采样策略。</li><li><strong>为什么会编</strong>：它优化的是「像不像人话」，不是「对不对」。</li><li><strong>为什么慢</strong>：每个 token 都要过一次模型，输出 500 token 就是 500 次前向（虽然有 KV Cache 复用）。</li></ol><h2 id="_2-token-与上下文窗口" tabindex="-1">2. Token 与上下文窗口 <a class="header-anchor" href="#_2-token-与上下文窗口" aria-label="Permalink to &quot;2. Token 与上下文窗口&quot;">​</a></h2><ul><li>一个汉字 ≈ 1～2 token，一个英文单词 ≈ 1～1.3 token；</li><li><strong>计费按 token</strong>，且<strong>输入和输出价格不同</strong>（输出通常贵 2～4 倍）；</li><li>上下文窗口是「输入 + 输出」的总和，<strong>输出也占额度</strong>。</li></ul><p><strong>为什么长上下文贵</strong>：注意力机制要对「每个 token 和之前所有 token」算相关性，计算量随长度<strong>平方</strong>增长（$O(n^2)$）。所以 128k 上下文的成本不是一个 16k 请求的 8 倍，而是高得多，延迟也明显变长。</p><p>工程含义：<strong>别把整个知识库塞进去</strong>，只放检索出来最相关的几段（见 <a href="./03-RAG体系">03 RAG</a>）。</p><h2 id="_3-transformer-与注意力-够用版" tabindex="-1">3. Transformer 与注意力（够用版） <a class="header-anchor" href="#_3-transformer-与注意力-够用版" aria-label="Permalink to &quot;3. Transformer 与注意力（够用版）&quot;">​</a></h2><p><strong>自注意力</strong>回答一个问题：当前这个词，应该多重关注前文的哪些词？</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">Query（我在找什么） × Key（每个词的标签） → 相关性分数</span></span>
<span class="line"><span style="color:#e1e4e8;">                    ↓ softmax 归一化</span></span>
<span class="line"><span style="color:#e1e4e8;">                对 Value（每个词的内容）加权求和</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">Query（我在找什么） × Key（每个词的标签） → 相关性分数</span></span>
<span class="line"><span style="color:#24292e;">                    ↓ softmax 归一化</span></span>
<span class="line"><span style="color:#24292e;">                对 Value（每个词的内容）加权求和</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>举例：「银行」这个词在「河边的银行」和「去银行取钱」里，注意力的落点完全不同 —— 这就是<strong>上下文消歧</strong>的原理。</p><p>必须知道的三个工程结论：</p><table><thead><tr><th>结论</th><th>原因</th></tr></thead><tbody><tr><td>长上下文成本平方增长</td><td>注意力矩阵 n×n</td></tr><tr><td><strong>KV Cache 能大幅加速</strong></td><td>已生成部分的 K/V 缓存复用，避免重算</td></tr><tr><td><strong>「Lost in the middle」</strong></td><td>放在上下文中间的信息容易被忽略，头尾更容易被利用</td></tr></tbody></table><h2 id="_4-采样参数-怎么让它稳定-发散" tabindex="-1">4. 采样参数：怎么让它稳定 / 发散 <a class="header-anchor" href="#_4-采样参数-怎么让它稳定-发散" aria-label="Permalink to &quot;4. 采样参数：怎么让它稳定 / 发散&quot;">​</a></h2><table><thead><tr><th>参数</th><th>作用</th><th>建议</th></tr></thead><tbody><tr><td><code>temperature</code></td><td>温度，越低越确定</td><td>事实问答 0～0.3；创意 0.7～1</td></tr><tr><td><code>top_p</code>（核采样）</td><td>只从累计概率前 p 的词里选</td><td>一般 0.9～0.95，<strong>和 temperature 只调一个</strong></td></tr><tr><td><code>top_k</code></td><td>只从概率最高的 k 个词里选</td><td>少用，<code>top_p</code> 更常用</td></tr><tr><td><code>repetition_penalty</code></td><td>惩罚重复</td><td>1.0～1.2，太高会不通顺</td></tr><tr><td><code>max_tokens</code></td><td>输出上限</td><td><strong>必设</strong>，防跑飞烧钱</td></tr><tr><td><code>stop</code></td><td>遇到指定串就停</td><td>结构化输出时很有用</td></tr><tr><td><code>seed</code></td><td>固定随机种子</td><td>要可复现（测试/评测）时用</td></tr></tbody></table><blockquote><p>经验：<strong>要稳定就 temperature=0 + 固定 seed</strong>，但注意很多厂商在 0 也不是完全确定的（并行计算导致浮点误差）。</p></blockquote><h2 id="_5-幻觉-成因与三层缓解" tabindex="-1">5. 幻觉：成因与三层缓解 <a class="header-anchor" href="#_5-幻觉-成因与三层缓解" aria-label="Permalink to &quot;5. 幻觉：成因与三层缓解&quot;">​</a></h2><table><thead><tr><th>层</th><th>手段</th></tr></thead><tbody><tr><td><strong>输入层</strong></td><td>提供资料（RAG）、限定「资料没有就说不知道」、Few-shot 给正确范式</td></tr><tr><td><strong>生成层</strong></td><td>降 temperature、要求引用出处、结构化输出（先给结论再给依据）</td></tr><tr><td><strong>输出层</strong></td><td>事后校验（规则/小模型/交叉验证）、关键数字走工具计算、人工兜底</td></tr></tbody></table><p><strong>认知</strong>：幻觉是「生成的本质」决定的，<strong>不可能消除</strong>。工程上追求的是「幻觉可发现、可拦截」，不是「没有幻觉」。</p><h2 id="_6-模型选型-四个维度" tabindex="-1">6. 模型选型：四个维度 <a class="header-anchor" href="#_6-模型选型-四个维度" aria-label="Permalink to &quot;6. 模型选型：四个维度&quot;">​</a></h2><table><thead><tr><th>维度</th><th>要问什么</th></tr></thead><tbody><tr><td><strong>能力</strong></td><td>任务复杂度（推理/代码/长文/多语言/多模态）够不够</td></tr><tr><td><strong>价格</strong></td><td>输入/输出单价 × 预估 token 量 = 每次调用成本</td></tr><tr><td><strong>延迟</strong></td><td>首 token 延迟（流式体验）+ 输出速度（tokens/s）</td></tr><tr><td><strong>合规</strong></td><td>数据能不能出境、能不能用于训练、要不要私有化</td></tr></tbody></table><p>常见组合策略：</p><ul><li><strong>主力 + 兜底</strong>：主力模型做业务，备用模型（不同厂商）防故障；</li><li><strong>大小搭配</strong>：简单意图识别/改写用小模型，复杂推理用大模型（见 <a href="./07-工程化落地">07 工程化</a> 的模型路由）；</li><li><strong>国内外双活</strong>：合规与稳定性兼顾。</li></ul><blockquote><p>别只看榜单。<strong>用自己的 20 条真实 badcase 跑一遍</strong>，比任何 benchmark 都准。</p></blockquote><h2 id="_7-部署-api-还是自己跑" tabindex="-1">7. 部署：API 还是自己跑 <a class="header-anchor" href="#_7-部署-api-还是自己跑" aria-label="Permalink to &quot;7. 部署：API 还是自己跑&quot;">​</a></h2><table><thead><tr><th>方式</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td><strong>云 API</strong></td><td>绝大多数业务，快速上线</td><td>按 token 付费、数据出域</td></tr><tr><td><strong>私有化部署开源模型</strong></td><td>数据不能出内网、量大到划算</td><td>机器成本 + 运维 + 调优</td></tr></tbody></table><h3 id="_7-1-推理引擎" tabindex="-1">7.1 推理引擎 <a class="header-anchor" href="#_7-1-推理引擎" aria-label="Permalink to &quot;7.1 推理引擎&quot;">​</a></h3><table><thead><tr><th>引擎</th><th>定位</th></tr></thead><tbody><tr><td><strong>vLLM</strong></td><td>生产首选，PagedAttention + 连续批处理，OpenAI 兼容接口</td></tr><tr><td><strong>Ollama</strong></td><td>本地开发最省事，GGUF 格式，一行命令跑起来</td></tr><tr><td><strong>SGLang / TensorRT-LLM</strong></td><td>极致性能，调优成本高</td></tr></tbody></table><p>两个关键优化：</p><ul><li><strong>PagedAttention</strong>：像操作系统分页一样管理 KV Cache，显存碎片大幅减少，吞吐提升数倍。</li><li><strong>连续批处理（Continuous Batching）</strong>：一个请求生成完立刻腾出位置给新请求，而不是等整批结束。</li></ul><h3 id="_7-2-量化" tabindex="-1">7.2 量化 <a class="header-anchor" href="#_7-2-量化" aria-label="Permalink to &quot;7.2 量化&quot;">​</a></h3><table><thead><tr><th>方案</th><th>位宽</th><th>场景</th></tr></thead><tbody><tr><td>GPTQ / AWQ</td><td>4bit</td><td>GPU 推理，精度损失小</td></tr><tr><td>GGUF</td><td>2~8bit</td><td>CPU / 混合，Ollama 用这个</td></tr><tr><td>FP8</td><td>8bit</td><td>新卡（H100 等）原生支持</td></tr></tbody></table><h3 id="_7-3-显存怎么算-面试常问" tabindex="-1">7.3 显存怎么算（面试常问） <a class="header-anchor" href="#_7-3-显存怎么算-面试常问" aria-label="Permalink to &quot;7.3 显存怎么算（面试常问）&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">显存 ≈ 权重 + KV Cache + 激活值</span></span>
<span class="line"><span style="color:#e1e4e8;">权重   = 参数量 × 每参数字节数（fp16=2B，int8=1B，int4=0.5B）</span></span>
<span class="line"><span style="color:#e1e4e8;">KV Cache ≈ 2 × 层数 × 头数 × head_dim × 序列长度 × batch × 字节数</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">显存 ≈ 权重 + KV Cache + 激活值</span></span>
<span class="line"><span style="color:#24292e;">权重   = 参数量 × 每参数字节数（fp16=2B，int8=1B，int4=0.5B）</span></span>
<span class="line"><span style="color:#24292e;">KV Cache ≈ 2 × 层数 × 头数 × head_dim × 序列长度 × batch × 字节数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>粗算经验：<strong>7B 模型 fp16 约 14GB 权重 + 余量 ≈ 16GB 显存</strong>；70B fp16 约 140GB，必须多卡或量化。</p><h2 id="_8-成本与延迟模型" tabindex="-1">8. 成本与延迟模型 <a class="header-anchor" href="#_8-成本与延迟模型" aria-label="Permalink to &quot;8. 成本与延迟模型&quot;">​</a></h2><p>一次调用的钱由三部分组成：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">成本 = 输入token × 输入单价 + 输出token × 输出单价 (+ 缓存命中折扣)</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">成本 = 输入token × 输入单价 + 输出token × 输出单价 (+ 缓存命中折扣)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>延迟分两段：</p><ul><li><strong>首 token 延迟（TTFT）</strong>：主要是 <strong>prefill</strong>（把整段输入算一遍），输入越长越慢；</li><li><strong>后续 token 速度（TPOT）</strong>：<strong>decode</strong> 阶段，通常 20～80 tokens/s，输出越长总时长越久。</li></ul><p><strong>优化方向</strong>：砍输入（RAG 只放 Top-K）、限输出（<code>max_tokens</code>、要求简洁）、缓存（相同前缀的 prompt cache）。</p><h2 id="_9-评测-别只看榜单" tabindex="-1">9. 评测：别只看榜单 <a class="header-anchor" href="#_9-评测-别只看榜单" aria-label="Permalink to &quot;9. 评测：别只看榜单&quot;">​</a></h2><table><thead><tr><th>类型</th><th>做法</th><th>局限</th></tr></thead><tbody><tr><td>公开榜（MMLU、C-Eval 等）</td><td>看个大概</td><td>和你的任务相关性低</td></tr><tr><td><strong>自建评测集</strong></td><td>20～200 条真实问题 + 标准答案/评分规则</td><td><strong>最有效</strong>，但要持续维护</td></tr><tr><td>LLM-as-judge</td><td>用强模型打分</td><td>有偏好偏差（偏爱长答案、偏爱同族模型）</td></tr><tr><td>人工抽检</td><td>定期抽样</td><td>贵，但必须有</td></tr></tbody></table><blockquote><p>落地顺序：先有 20 条 badcase 组成的最小评测集，再谈优化。没有评测集的「调优」都是玄学。</p></blockquote><h2 id="_10-速查表" tabindex="-1">10. 速查表 <a class="header-anchor" href="#_10-速查表" aria-label="Permalink to &quot;10. 速查表&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>LLM 本质</td><td>自回归预测下一个 token 的概率分布，采样生成</td></tr><tr><td>为什么长上下文贵</td><td>注意力 O(n²)，且输入按 token 计费</td></tr><tr><td>temperature</td><td>控制采样随机性，事实任务用 0～0.3</td></tr><tr><td>top_p 与 temperature</td><td>都是采样参数，一般只调一个</td></tr><tr><td>KV Cache</td><td>缓存已算的 K/V，decode 阶段不必重算前文</td></tr><tr><td>幻觉能消除吗</td><td>不能，只能靠 RAG + 低温度 + 引用 + 事后校验缓解</td></tr><tr><td>模型怎么选</td><td>能力/价格/延迟/合规四维，用自己的 badcase 测</td></tr><tr><td>显存怎么估</td><td>参数量 × 字节数 + KV Cache，7B fp16 ≈ 16GB</td></tr><tr><td>vLLM 强在哪</td><td>PagedAttention + 连续批处理，吞吐数倍提升</td></tr><tr><td>首 token 为什么慢</td><td>prefill 要把整段输入算一遍</td></tr></tbody></table>`,50)]))}const u=e(r,[["render",o]]);export{b as __pageData,u as default};
